//! Fixed-capacity LRU cache with O(1) expected-time operations.
//!
//! Entries live in a slab of slots; recency order is an intrusive doubly
//! linked list over slot indices, and a hash map resolves keys to slots.

use std::collections::HashMap;
use std::hash::Hash;

const NIL: usize = usize::MAX;

#[derive(Debug)]
struct Slot<K, V> {
    key: K,
    value: V,
    prev: usize,
    next: usize,
}

/// A least-recently-used cache holding at most `capacity` entries.
#[derive(Debug)]
pub struct LruCache<K, V> {
    capacity: usize,
    index: HashMap<K, usize>,
    slots: Vec<Option<Slot<K, V>>>,
    free: Vec<usize>,
    /// Most recently used slot.
    head: usize,
    /// Least recently used slot.
    tail: usize,
}

impl<K: Hash + Eq + Clone, V> LruCache<K, V> {
    /// Creates an empty cache.
    ///
    /// # Panics
    ///
    /// Panics if `capacity` is zero.
    pub fn new(capacity: usize) -> Self {
        assert!(capacity > 0, "capacity must be positive");
        Self {
            capacity,
            index: HashMap::new(),
            slots: Vec::new(),
            free: Vec::new(),
            head: NIL,
            tail: NIL,
        }
    }

    /// Number of entries currently held.
    pub fn len(&self) -> usize {
        self.index.len()
    }

    /// Returns `true` if the cache holds no entries.
    #[allow(dead_code)] // Kept alongside `len` for a complete API.
    pub fn is_empty(&self) -> bool {
        self.index.is_empty()
    }

    /// Looks up `key`; a hit marks it as the most recently used.
    pub fn get<Q>(&mut self, key: &Q) -> Option<&V>
    where
        K: std::borrow::Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        let slot = *self.index.get(key)?;
        self.move_to_front(slot);
        Some(&self.slot(slot).value)
    }

    /// Inserts or overwrites `key`, making it the most recently used.
    /// Evicts the least recently used entry if the cache would overflow.
    pub fn set(&mut self, key: K, value: V) {
        if let Some(&slot) = self.index.get(&key) {
            self.slot_mut(slot).value = value;
            self.move_to_front(slot);
            return;
        }
        if self.index.len() >= self.capacity {
            self.evict_least_recent();
        }

        let entry = Slot {
            key: key.clone(),
            value,
            prev: NIL,
            next: NIL,
        };
        let slot = match self.free.pop() {
            Some(slot) => {
                self.slots[slot] = Some(entry);
                slot
            }
            None => {
                self.slots.push(Some(entry));
                self.slots.len() - 1
            }
        };
        self.index.insert(key, slot);
        self.push_front(slot);
    }

    /// Removes `key`, returning `true` if it was present.
    pub fn remove<Q>(&mut self, key: &Q) -> bool
    where
        K: std::borrow::Borrow<Q>,
        Q: Hash + Eq + ?Sized,
    {
        match self.index.remove(key) {
            Some(slot) => {
                self.release(slot);
                true
            }
            None => false,
        }
    }

    fn evict_least_recent(&mut self) {
        if self.tail != NIL {
            let evicted = self.release(self.tail);
            self.index.remove(&evicted.key);
        }
    }

    /// Unlinks a slot and returns it to the free list, yielding its entry.
    /// The caller is responsible for removing the key from the index.
    fn release(&mut self, slot: usize) -> Slot<K, V> {
        self.unlink(slot);
        self.free.push(slot);
        self.slots[slot].take().expect("live slot")
    }

    fn slot(&self, slot: usize) -> &Slot<K, V> {
        self.slots[slot].as_ref().expect("live slot")
    }

    fn slot_mut(&mut self, slot: usize) -> &mut Slot<K, V> {
        self.slots[slot].as_mut().expect("live slot")
    }

    fn move_to_front(&mut self, slot: usize) {
        if slot != self.head {
            self.unlink(slot);
            self.push_front(slot);
        }
    }

    fn push_front(&mut self, slot: usize) {
        let old_head = self.head;
        {
            let entry = self.slot_mut(slot);
            entry.prev = NIL;
            entry.next = old_head;
        }
        if old_head != NIL {
            self.slot_mut(old_head).prev = slot;
        }
        self.head = slot;
        if self.tail == NIL {
            self.tail = slot;
        }
    }

    fn unlink(&mut self, slot: usize) {
        let (prev, next) = {
            let entry = self.slot(slot);
            (entry.prev, entry.next)
        };
        if prev != NIL {
            self.slot_mut(prev).next = next;
        } else {
            self.head = next;
        }
        if next != NIL {
            self.slot_mut(next).prev = prev;
        } else {
            self.tail = prev;
        }
    }
}

#[cfg(test)]
mod tests {
    use super::LruCache;

    #[test]
    fn evicts_least_recently_used() {
        let mut cache = LruCache::new(2);
        cache.set("a", 1);
        cache.set("b", 2);
        assert_eq!(cache.get("a"), Some(&1));
        cache.set("c", 3);
        assert_eq!(cache.get("b"), None);
        assert_eq!(cache.len(), 2);
    }

    #[test]
    fn overwrite_refreshes_recency() {
        let mut cache = LruCache::new(2);
        cache.set("a", 1);
        cache.set("b", 2);
        cache.set("a", 9);
        cache.set("c", 3);
        assert_eq!(cache.get("a"), Some(&9));
        assert_eq!(cache.get("b"), None);
    }

    #[test]
    fn remove_reports_presence() {
        let mut cache = LruCache::new(3);
        cache.set("x", 1);
        assert!(cache.remove("x"));
        assert!(!cache.remove("x"));
        assert!(cache.is_empty());
        cache.set("y", 2);
        assert_eq!(cache.get("y"), Some(&2));
    }
}

//! Command-line LRU cache simulator (see SPEC.md).
//!
//! Input is treated as raw bytes so that any key or value round-trips exactly.

mod lru_cache;

use std::io::{self, BufWriter, Read, Write};

use lru_cache::LruCache;

const NULL_REPLY: &[u8] = b"NULL";

/// Runs the command script in `input`, writing one reply line per query.
fn run(input: &[u8], out: &mut impl Write) -> io::Result<()> {
    let mut lines = input.split(|&b| b == b'\n');
    let Some(capacity) = lines.next().and_then(parse_capacity) else {
        return Ok(());
    };

    let mut cache: LruCache<Box<[u8]>, Box<[u8]>> = LruCache::new(capacity);

    for line in lines {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        if line.is_empty() {
            continue;
        }

        let (command, rest) = split_once_space(line).unwrap_or((line, b""));
        match command {
            b"SET" => {
                if let Some((key, value)) = split_once_space(rest) {
                    cache.set(key.into(), value.into());
                }
            }
            b"GET" => {
                out.write_all(cache.get(rest).map_or(NULL_REPLY, |v| v))?;
                out.write_all(b"\n")?;
            }
            b"DEL" => {
                out.write_all(if cache.remove(rest) { b"1\n" } else { b"0\n" })?;
            }
            b"SIZE" => writeln!(out, "{}", cache.len())?,
            // Unknown commands are ignored.
            _ => {}
        }
    }
    Ok(())
}

fn split_once_space(s: &[u8]) -> Option<(&[u8], &[u8])> {
    let at = s.iter().position(|&b| b == b' ')?;
    Some((&s[..at], &s[at + 1..]))
}

/// Parses the capacity line leniently: leading whitespace, an optional sign,
/// then a run of decimal digits; anything after the digits is ignored.
/// Returns `None` unless the result is a positive integer.
fn parse_capacity(line: &[u8]) -> Option<usize> {
    let is_space = |b: &u8| matches!(b, b'\t' | b'\n' | 0x0b | 0x0c | b'\r' | b' ' | 0xa0);
    let start = line.iter().position(|b| !is_space(b)).unwrap_or(line.len());
    let s = &line[start..];

    let digits = match s.first() {
        // Any negative value (or -0) is not a valid capacity.
        Some(b'-') => return None,
        Some(b'+') => &s[1..],
        _ => s,
    };
    parse_digits(digits).filter(|&n| n >= 1)
}

/// Parses leading decimal digits, saturating on overflow.
fn parse_digits(s: &[u8]) -> Option<usize> {
    let len = s.iter().take_while(|b| b.is_ascii_digit()).count();
    if len == 0 {
        return None;
    }
    let value = s[..len].iter().fold(0usize, |acc, &d| {
        acc.saturating_mul(10).saturating_add(usize::from(d - b'0'))
    });
    Some(value)
}

fn main() -> io::Result<()> {
    let mut input = Vec::new();
    io::stdin().lock().read_to_end(&mut input)?;

    let mut out = BufWriter::with_capacity(1 << 16, io::stdout().lock());
    run(&input, &mut out)?;
    out.flush()
}

#[cfg(test)]
mod tests {
    use super::{parse_capacity, run};

    fn run_str(input: &str) -> String {
        let mut out = Vec::new();
        run(input.as_bytes(), &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn spec_example() {
        let input = "2\nSET a 1\nSET b 2\nGET a\nSET c 3\nGET b\nSIZE\n";
        assert_eq!(run_str(input), "1\nNULL\n2\n");
    }

    #[test]
    fn capacity_parsing() {
        assert_eq!(parse_capacity(b"3"), Some(3));
        assert_eq!(parse_capacity(b" +7x"), Some(7));
        assert_eq!(parse_capacity(b"2\r"), Some(2));
        assert_eq!(parse_capacity(b"0"), None);
        assert_eq!(parse_capacity(b"-4"), None);
        assert_eq!(parse_capacity(b"abc"), None);
        assert_eq!(parse_capacity(b""), None);
    }

    #[test]
    fn invalid_capacity_prints_nothing() {
        assert_eq!(run_str("0\nSET a 1\nSIZE\n"), "");
    }
}
